sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below
   var ga = new GlideAjax("getEmailAddress");
   var user_sys_id = g_user.userID;
   ga.addParam("sysparm_name", "getEmail");
   ga.addParam("sysparm_userID", user_sys_id);
   ga.getXMLAnswer(preencherCampoEmail);

   function preencherCampoEmail(response){
		var email = response;
		g_form.clearValue("u_requested_for_email");
		g_form.setValue("u_requested_for_email", email);
   }
}
